package com.nexbank.auth.web;
import com.nexbank.auth.dto.AuthDtos.*;import com.nexbank.auth.service.AuthService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;public AuthController(AuthService auth){this.auth=auth;}@PostMapping("/register") public TokenResponse register(@Valid @RequestBody Credentials body){return auth.register(body);}@PostMapping("/login") public TokenResponse login(@Valid @RequestBody Credentials body){return auth.login(body);}@PostMapping("/refresh") public TokenResponse refresh(@Valid @RequestBody RefreshRequest body){return auth.refresh(body.refreshToken());}@PostMapping("/logout") @ResponseStatus(HttpStatus.NO_CONTENT) public void logout(@RequestHeader("Authorization") String authorization,@Valid @RequestBody LogoutRequest body){auth.logout(authorization,body.refreshToken());}}
